<template>
  <apexchart :type="chart.kind" height="300" :options="lineOptions" :series="series" />
</template>

<script>
import VueApexCharts from "vue3-apexcharts";
import { COLORS } from "@/utils/dashboardData";
import { buildDrillPayload } from "@/utils/dashboardMapper";

export default {
  name: "LineAreaChart",
  components: { apexchart: VueApexCharts },
  props: { chart: { type: Object, required: true } },
  emits: ["drill"],

  computed: {
    series() {
      return [{ name: this.chart.title, data: this.chart.series }];
    },
    lineOptions() {
      return {
        chart: {
          toolbar: { show: false },
          events: {
            dataPointSelection: this.onPointClick,
            markerClick: this.onPointClick,
          },
        },
        xaxis: { categories: this.chart.categories },
        colors: [COLORS.blue],
        stroke: { curve: "smooth", width: 3 },
        markers: { size: 5, hover: { size: 7 } },
        dataLabels: { enabled: false },
        grid: { strokeDashArray: 4 },
      };
    },
  },

  methods: {
    onPointClick(e, ctx, cfg) {
      const i = cfg.dataPointIndex;
      if (i == null || i < 0) return;
      this.$emit("drill", buildDrillPayload(this.chart, i));
    },
  },
};
</script>
