<template>
  <v-app>
    <v-navigation-drawer permanent rail v-if="screen !== 'type' && screen !== 'form'">
      <v-list nav density="compact">
        <v-list-item
          v-for="item in navItems"
          :key="item.id"
          :prepend-icon="item.icon"
          :title="item.label"
          color="primary"
          :active="screen === item.id"
          @click="screen = item.id"
        />
      </v-list>
    </v-navigation-drawer>

    <v-main class="bg-grey-lighten-4 app-main">
      <div class="app-content">
        <TypeSelectionView
          v-if="screen === 'type'"
          @open-form="screen = 'form'"
          @open-dashboard="onOpenDashboard"
          @open-saved-view="onOpenSavedView"
        />
        <CustomFormView
          v-else-if="screen === 'form'"
          @open-dashboard="onOpenDashboard"
          @go-home="screen = 'type'"
        />
        <DashboardView
          v-else-if="screen === 'dashboard'"
          :restore-view="pendingView"
        />

        <SavedViewsView
          v-else-if="screen === 'saved'"
          @open="onOpenSavedView"
        />

        <div v-else class="pa-8 text-center text-medium-emphasis">
          Coming soon
        </div>
      </div>
    </v-main>
    <AppToast />
  </v-app>
</template>

<script>
import TypeSelectionView from "@/views/TypeSelectionView.vue";
import DashboardView from "@/views/DashboardView.vue";
import SavedViewsView from "@/views/SavedViewsView.vue";
import AppToast from "@/components/common/AppToast.vue";
import { useDashboardStore } from "@/store/dashboardStore";
import CustomFormView from "@/views/CustomFormView.vue";
export default {
  name: "App",
  setup() {
    return { store: useDashboardStore() };
  },
  components: {
    TypeSelectionView,
    DashboardView,
    SavedViewsView,
    AppToast,
    CustomFormView
  },
  watch: {
    screen(newScreen) {
      if (newScreen === "type") {
        this.store.setCustomForm(null);
        this.widget?.setTitle("Attribute Driven Dashboard Widget");
      }
    },
  },
  props: {
    widget: { type: Object, default: null },
  },
  data() {
    return {
      pendingView: null,
      screen: "type",
      navItems: [
        { id: "type", icon: "mdi-home-outline", label: "Home" },
        { id: "dashboard", icon: "mdi-chart-line", label: "Dashboard" },
        { id: "saved", icon: "mdi-bookmark-outline", label: "Saved Views" },
        { id: "info", icon: "mdi-information-outline", label: "Info" },
      ],
    };
  },

  computed: {
    currentYear() {
      return new Date().getFullYear();
    },
  },

  methods: {
    onOpenSavedView(view) {
      this.widget?.setTitle(view.name || "Saved View");
      this.pendingView = view;
      this.screen = "dashboard";
    },
    onOpenDashboard() {
      this.widget?.setTitle(this.store.type || "Dashboard");
      this.pendingView = null;
      this.screen = "dashboard";
    },
  },
};
</script>

<style lang="scss">
@use "@/assets/styles/dashboard.scss";
</style>

<style scoped>
.app-main {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}
.app-content {
  flex: 1;
}
.app-footer {
  text-align: center;
  font-size: 11px;
  color: #999;
  padding: 10px;
}
@media (max-width: 480px) {
  .app-footer { font-size: 10px; padding: 6px; }
}
</style>