<template>
  <apexchart type="bar" height="300" :options="barOptions" :series="series" />
</template>

<script>
import VueApexCharts from "vue3-apexcharts";
import { COLORS } from "@/utils/dashboardData";
import { buildDrillPayload } from "@/utils/dashboardMapper";

export default {
  name: "BarChart",
  components: { apexchart: VueApexCharts },
  props: {
    chart: { type: Object, required: true },
    horizontal: { type: Boolean, default: false },
  },
  emits: ["drill"],

  computed: {
    series() {
      return [{ name: this.chart.title, data: this.chart.series }];
    },
    barOptions() {
      return {
        chart: {
          toolbar: { show: false },
          events: {
            dataPointSelection: (e, ctx, cfg) => this.drill(cfg.dataPointIndex),
          },
        },
        plotOptions: { bar: { horizontal: this.horizontal, barHeight: "55%" } },
        xaxis: { categories: this.chart.categories },
        colors: [COLORS.blue],
        dataLabels: { enabled: false },
        grid: { strokeDashArray: 4 },
      };
    },
  },

  methods: {
    drill(index) {
      this.$emit("drill", buildDrillPayload(this.chart, index));
    },
  },
};
</script>
