<template>
    <div class="cf-wrap">
        <div class="cf-panel">
            <div class="cf-head">
                <div class="cf-icon"><v-icon icon="mdi-form-select" size="22" /></div>
                <div>
                    <h2 class="cf-title">Custom Query</h2>
                    <div class="cf-sub">Set your criteria and we'll build the dashboard from them</div>
                </div>
            </div>

            <div class="cf-body">
                <section v-for="(list, name) in sections" :key="name" class="cf-section">
                    <div class="cf-section-title">{{ name }}</div>
                    <div class="cf-grid">
                        <template v-for="f in list" :key="f.key">
                            <v-select v-if="f.key === 'type'" v-model="form.type" :items="f.items" :label="f.label"
                                variant="outlined" density="comfortable" hide-details />
                            <v-text-field v-else-if="f.date" v-model="form[f.key]" type="date" :label="f.label"
                                variant="outlined" density="comfortable" hide-details />
                            <v-combobox v-else v-model="form[f.key]" :items="f.items || []" :label="f.label"
                                hide-no-data clearable variant="outlined" density="comfortable" hide-details />
                        </template>
                    </div>
                </section>
            </div>

            <div class="cf-actions">
                <button class="btn-outline cf-home" @click="$emit('go-home')">
                    <v-icon icon="mdi-home-outline" size="16" /> Home
                </button>
                <button class="btn-outline" @click="reset">Clear all</button>
                <button class="btn-primary" :disabled="!form.type" @click="submit">Show Dashboard</button>
            </div>
        </div>
    </div>
</template>

<script>
import { useDashboardStore } from "@/store/dashboardStore";

const STATUS = ["IN_WORK", "RELEASED", "OBSOLETE", "FROZEN"];
const KEYS = ["type", "keyword", "status", "policy", "owner", "lastModifiedBy", "originator", "project", "createdFrom", "createdTo", "modifiedFrom", "modifiedTo"];
const EMPTY = () => Object.fromEntries(KEYS.map((k) => [k, ""]));

export default {
    name: "CustomFormView",
    setup() {
        return { store: useDashboardStore() };
    },
    data() {
        return { form: { ...EMPTY(), type: this.store.type } };
    },
    computed: {
        fields() {
            return [
                { key: "type", label: "Object type", section: "General", items: this.store.getTypeOptions.map((t) => t.name) },
                { key: "keyword", label: "Keyword", section: "General" },
                { key: "status", label: "Maturity state", section: "Attributes", items: STATUS },
                { key: "policy", label: "Policy", section: "Attributes", items: ["Document Release", "VPLM_SMB_Definition"] },
                { key: "owner", label: "Owner", section: "People" },
                { key: "lastModifiedBy", label: "Last modified by", section: "People" },
                { key: "originator", label: "Originator", section: "People" },
                { key: "project", label: "Collaborative space", section: "People" },
                { key: "createdFrom", label: "Created from", section: "Dates", date: true },
                { key: "createdTo", label: "Created to", section: "Dates", date: true },
                { key: "modifiedFrom", label: "Modified from", section: "Dates", date: true },
                { key: "modifiedTo", label: "Modified to", section: "Dates", date: true },
            ];
        },
        sections() {
            const out = {};
            this.fields.forEach((f) => (out[f.section] ||= []).push(f));
            return out;
        },
    },
    methods: {
        reset() {
            this.form = EMPTY();
        },
        submit() {
            const { type, ...values } = this.form;
            Object.keys(values).forEach((k) => (values[k] = values[k] || ""));
            this.store.setType(type); // also clears old form
            this.store.setCustomForm(values);
            this.$emit("open-dashboard", {});
        },
    },
};
</script>

<style scoped>
.cf-wrap {
    display: flex;
    justify-content: center;
    padding: 24px 16px;
}

.cf-panel {
    width: 100%;
    max-width: 760px;
    max-height: calc(100vh - 48px);
    display: flex;
    flex-direction: column;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    overflow: hidden;
}

.cf-head {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 20px 28px;
    border-bottom: 1px solid #eee;
}

.cf-icon {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    background: rgba(15, 98, 254, 0.08);
    color: #0f62fe;
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
}

.cf-title {
    font-size: 18px;
    font-weight: 700;
    margin: 0 0 2px;
    color: #1a1a1a;
}

.cf-sub {
    font-size: 13px;
    color: #666;
}

.cf-body {
    flex: 1;
    overflow-y: auto;
    padding: 8px 28px 4px;
}

.cf-section {
    padding: 16px 0;
    border-bottom: 1px solid #f0f0f0;
}

.cf-section:last-child {
    border-bottom: 0;
}

.cf-section-title {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #888;
    margin-bottom: 12px;
}

.cf-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
}

.cf-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 14px 28px;
    border-top: 1px solid #eee;
    background: #fafafa;
}

.cf-actions button {
    height: 38px;
    padding: 0 20px;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s, box-shadow 0.15s, transform 0.1s;
}

.cf-actions .btn-outline {
    background: #fff;
    color: #444;
    border: 1px solid #ccc;
}

.cf-actions .btn-outline:hover {
    background: #f5f7fa;
    border-color: #999;
}

.cf-actions .btn-primary {
    background: #0f62fe;
    color: #fff;
    border: 1px solid #0f62fe;
}

.cf-actions .btn-primary:hover {
    background: #0a4fd1;
    box-shadow: 0 2px 8px rgba(15, 98, 254, 0.35);
}

.cf-actions .btn-primary:disabled {
    background: #b9c9e8;
    border-color: #b9c9e8;
    box-shadow: none;
    cursor: not-allowed;
}

.cf-actions button:active:not(:disabled) {
    transform: scale(0.97);
}

@media (max-width: 600px) {
    .cf-grid {
        grid-template-columns: 1fr;
    }

    .cf-head,
    .cf-body,
    .cf-actions {
        padding-left: 16px;
        padding-right: 16px;
    }
}

.cf-home {
    margin-right: auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}
</style>