import { initWidget, x3DDashboardUtils } from "./config/widgetConfig";
import { createApp } from "vue";
import pinia from "./store";
import initApp from "./utils/initApp";
import { useDashboardStore } from "@/store/dashboardStore";

import App from "./App.vue";
import vuetify from "./plugins/vuetify";
function createVueApp(widget) {
  const app = createApp(App,{widget});
  app.use(pinia);
  app.use(vuetify);
  return app;
}

if (process.env.VUE_APP_BUILD_TARGET === "widget") {
  initWidget(async (widget) => {
    const app = createVueApp(widget);
    await initApp.get3DSpaceURL();
    await initApp.getUserDetails();
    await initApp.userCtxCollabspaces(widget);
    await useDashboardStore(pinia).fetchTypeConfig();
    app.mount("#app");
    x3DDashboardUtils.disableCSS();
    widget.addEvent("onLoad", () => app);
  });
} else {
  const app = createVueApp();
  useDashboardStore(pinia).fetchTypeConfig();
  app.mount("#app");
}
